      // Distância SL = (Preço de Entrada - SL)
      double sl_distance = Ask - stop_loss_buy;
      double take_profit_buy = Ask + (sl_distance * Risk_Reward_Ratio); // Corrigido o cálculo

      int buy_ticket = OrderSend(Symbol(), OP_BUY, Lots, Ask, slippage, stop_loss_buy, take_profit_buy, "Buy order", 0, 0, clrGreen);
      if(buy_ticket < 0)
